const fs = require("fs");
const path = require("path");
const cp = require("child_process");
const dir = "/w/attachdir";
fs.rmSync(dir, { recursive: true, force: true });
fs.mkdirSync(dir, { recursive: true });
fs.writeFileSync(path.join(dir, "data.txt"), "hello\n");
fs.writeFileSync(path.join(dir, "note.test.mjs"), [
  "import { test } from 'vitest'",
  "test('note', async ({ annotate }) => {",
  "  await annotate('see data', 'notice', { path: 'data.txt' })",
  "})",
].join("\n") + "\n");
const r = cp.spawnSync(process.execPath, ["/w/node_modules/vitest/vitest.mjs", "run"], {
  cwd: dir,
  encoding: "utf8",
  env: { ...process.env, NO_COLOR: "1", CI: "1" },
  timeout: 60000,
});
console.log((r.stdout || "") + (r.stderr || "") + (r.error ? String(r.error) : ""));
function list(sub) {
  try { return fs.readdirSync(path.join(dir, sub)); } catch { return []; }
}
const newFiles = list(".vitest/attachments");
const oldFiles = list(".vitest-attachments");
console.log("in .vitest/attachments: " + JSON.stringify(newFiles) + ", in .vitest-attachments: " + JSON.stringify(oldFiles));
if (r.status !== 0) {
  console.error("ERROR: vitest run failed (exit " + r.status + ")");
  process.exit(2);
}
if (newFiles.length === 1 && oldFiles.length === 0) {
  console.log("PASS: with attachmentsDir unset, the attachment was copied into .vitest/attachments");
  process.exit(0);
}
if (oldFiles.length === 1 && newFiles.length === 0) {
  console.error("FAIL: with attachmentsDir unset, the attachment was copied into .vitest-attachments, not .vitest/attachments");
  process.exit(1);
}
console.error("ERROR: attachment not found in either directory");
process.exit(2);

